    <script>
        const table = document.getElementById('sudoku');
        const cells = Array.from(table.getElementsByTagName('td'));
        const solution = [
            3, 0, 6, 5, 0, 8, 4, 0, 0,
            5, 2, 0, 0, 0, 0, 0, 0, 0,
            0, 8, 7, 0, 0, 0, 0, 3, 1,
